head.script:
scwin.screenId = "jldbnf30002";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const tmp_dtl_coupn_rt = $("#ipt_dtlCoupnRt", parent.opener.document).val();
        if (tmp_dtl_coupn_rt != null) {
            for (let r = 0, n = $c.util.getComponent('dlt_result').getTotalRow(); r < n; r++) {const idx = r; 
                const par_dtl_coupn_rt = $("#tbl_coupnRt > tbody", parent.opener.document).find("tr:eq(" + idx + ")").find("#dtl_coupn_rt").val();
                $c.util.getComponent('dlt_result').setCellData(r, 'coupnRt', par_dtl_coupn_rt);
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30002.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":5
        ,"mmenu":9
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30002' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf30002.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_openStripYd_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_openStripYd_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_openStripYd_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.openStripYd()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30002.btn_openStripYd_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_save_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.save()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30002.btn_save_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_close_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30002.btn_close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_openStripYd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_openStripYd = async function () {
    const sbmOptions = {
        id: "tx_fn_openStripYd",
        method: "post",
        action: "/strip/strip.do?method=searchStripYdList",
        ref: "dma_openStripYdReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf30002.tx_fn_openStripYd" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.openStripYd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openStripYd = async function () {
    /* sdd-asis-lifecycle:begin fn_openStripYd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const width = 1000;
    const height = 800;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/strip/strip.do?method=searchStripYdList", unresolved: "nav:" + "/strip/strip.do?method=searchStripYdList" }; })();
    const fm = (document.searchForm || { elements: [] });
    const date = new Date();
    const year = date.getFullYear();
    const mm = ((date.getMonth() + 1) < 10 ? '0' + (date.getMonth() + 1) : (date.getMonth() + 1));
    const day = (date.getDate() < 10 ? '0' + date.getDate() : date.getDate());
    const today = year.toString() + "-" + mm.toString() + "-" + day.toString();
    $c.util.getComponent('dma_openStripYdReq').set('strtDd', today);
    fm.action = '/strip/strip.do?method=searchStripYdList';

    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.checkData()) {
        return;
    }
    const parentform = parent.opener.document;
    const newItem = $c.util.getComponent('coupnRtList').getValue();
    $("#tbl_coupnRt", parentform).empty().html(newItem);
    $("#tbl_coupnRt > tbody > tr", parentform).each(function(idx) {
            const data = $("#coupnRtList > tbody > tr:eq(" + idx + ") > td:eq(6)").find("#dtl_coupn_rt").val();
            $(this).find('td').eq(6).find("#dtl_coupn_rt").val(data);
    });
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkData = async function () {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let returnYn = true;
    for (let r = 0, n = $c.util.getComponent('dlt_result').getTotalRow(); r < n; r++) {const idx = r; /* 수동 전환 필요: DOM 관용구 $(this) 잔존 — 행 순회 안에서 해석 못 함(D19-b) */
        const rowIdx = idx + 1;
        if ($c.util.getComponent('dlt_result').getCellData(r, 'sprtParAmt') === '') {
            returnYn = false;
            await $c.win.alert(rowIdx + "번째 행의 분리신청액면금액을 입력하십시오");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        } else {
            if ($c.util.getComponent('dlt_result').getCellData(r, 'coupnRt') === '') {
                returnYn = false;
                await $c.win.alert(rowIdx + "번째 행의 표면이자율을 입력하십시오");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return false;
            } else {
                if ($c.util.getComponent('dlt_result').getCellData(r, 'coupnRt') >= 100) {
                    returnYn = false;
                    await $c.win.alert(rowIdx + "번째 행의 표면이자율을 확인하십시오.");
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                } else {
                    if (fn_minusCheck2($(this).find("#dtl_coupn_rt"), rowIdx + "번째 행의 표면이자율") === "N") {
                        returnYn = false;
                        return false;
                    }
                }
            }
        }
    }
    return returnYn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
